/* Adversarial paraphrase generation.
 *
 * Every mandatory case is re-asked in forms nobody wrote runtime code for:
 * typos, stripped punctuation, reordered relations, politeness wrappers and
 * different question stems. The expectation is unchanged -- if a paraphrase
 * fails where the original passes, the mechanism generalised to a wording
 * rather than to a meaning, and that is an overfit worth fixing.
 *
 * These variants exist only here. Nothing generated by this file is visible
 * to runtime code.
 *
 *   node tools/lm-paraphrase.js --out measurements/lm-paraphrase.json
 */
"use strict";
var fs = require("fs");
var path = require("path");
var rt = require("./lm-runtime.js");
var CASES = require("./lm-tests.js").CASES;

function arg(n, d) { var i = process.argv.indexOf("--" + n); return i < 0 ? d : (process.argv[i + 1] || true); }
var OUT = String(arg("out", "measurements/lm-paraphrase.json"));
var LIMIT = Number(arg("limit", 0));

/* ---------------------------------------------------------- generators */

function stripPunct(q) { return q.replace(/[?.!,]/g, "").trim(); }
function lower(q) { return q.toLowerCase(); }

function typo(q) {
  /* Transpose two adjacent letters inside the longest content word. */
  var words = q.split(/(\s+)/);
  var bestI = -1, bestLen = 0;
  for (var i = 0; i < words.length; i++) {
    var w = words[i].replace(/[^A-Za-z]/g, "");
    if (w.length > bestLen && w.length >= 6) { bestLen = w.length; bestI = i; }
  }
  if (bestI < 0) return null;
  var w2 = words[bestI], j = Math.floor(w2.length / 2);
  if (j + 1 >= w2.length) return null;
  words[bestI] = w2.slice(0, j) + w2.charAt(j + 1) + w2.charAt(j) + w2.slice(j + 2);
  return words.join("");
}

function politeWrap(q) {
  var body = q.replace(/^(?:what|who|why|how|when|where|which)\b/i, function (m) { return m.toLowerCase(); });
  return "hey, could you tell me " + body.replace(/\?$/, "") + "?";
}

function stemSwap(q) {
  var map = [
    [/^what is the (.+?) of (.+?)\?$/i, "$2's $1?"],
    [/^what is the (.+?) of (.+?)\?$/i, "which one is the $1 of $2?"],
    [/^what is (?:a |an |the )?(.+?)\?$/i, "define $1"],
    [/^what is (?:a |an |the )?(.+?)\?$/i, "can you describe $1"],
    [/^who wrote (.+?)\?$/i, "who is the author of $1?"],
    [/^why (?:does|do|is|are) (.+?)\?$/i, "what causes $1?"],
    [/^compare (.+?) and (.+?)\.?$/i, "what's the difference between $1 and $2?"],
    [/^explain (.+?)\.?$/i, "give me a short explanation of $1"],
    [/^what is (\d.+?)\?$/i, "calculate $1"],
    [/^tell me about (.+?)\.?$/i, "what do you know about $1?"]
  ];
  for (var i = 0; i < map.length; i++) {
    if (map[i][0].test(q)) return q.replace(map[i][0], map[i][1]);
  }
  return null;
}

function fragment(q) {
  /* The search-box form: content words only, no syntax. */
  var stop = /^(?:what|which|who|whom|whose|when|where|why|how|is|are|was|were|do|does|did|can|could|the|a|an|of|in|on|for|to|me|tell|about|please|explain|give|and|that|it)$/i;
  var toks = q.replace(/[?.!,]/g, "").split(/\s+/).filter(function (t) { return !stop.test(t); });
  if (toks.length < 1 || toks.length > 5) return null;
  return toks.join(" ");
}

function verbose(q) {
  return "I've been wondering about something and would appreciate your help: " +
    q.replace(/^(?:what|who|why|how|when|where|which)\b/i, function (m) { return m.toLowerCase(); });
}

var GENERATORS = [
  { id: "lowercase-nopunct", fn: function (q) { return lower(stripPunct(q)); } },
  { id: "typo", fn: typo },
  { id: "stem-swap", fn: stemSwap },
  { id: "polite-wrap", fn: politeWrap },
  { id: "fragment", fn: fragment },
  { id: "verbose-wrap", fn: verbose }
];

/* Cases whose wording IS the test (format instructions, dialogue sequences,
   deliberately malformed input) are not paraphrased: changing the wording
   would change what is being measured. */
function paraphrasable(c) {
  if (c.turns) return false;
  if (!c.q || c.q.length < 8) return false;
  if (c.cat === "format" || c.cat === "edge" || c.cat === "robust" || c.cat === "chat" ||
      c.cat === "remark" || c.cat === "site") return false;
  return true;
}

function matchOne(text, pat) {
  if (pat instanceof RegExp) return pat.test(text);
  return String(text).toLowerCase().indexOf(String(pat).toLowerCase()) >= 0;
}

async function main() {
  var offline = function () { return Promise.reject(new Error("offline")); };
  var out = [], stats = { total: 0, pass: 0, byGenerator: {} };
  var cases = CASES.filter(paraphrasable);
  if (LIMIT) cases = cases.slice(0, LIMIT);

  for (var i = 0; i < cases.length; i++) {
    var c = cases[i];
    for (var g = 0; g < GENERATORS.length; g++) {
      var variant;
      try { variant = GENERATORS[g].fn(c.q); } catch (e) { variant = null; }
      if (!variant || variant.toLowerCase() === c.q.toLowerCase()) continue;
      var win = rt.boot({ fetch: offline });
      var res = await rt.askOnce(win, variant, 20000);
      var text = res.text || "";
      var ok = true, issues = [];
      (c.expectAll || []).forEach(function (p) { if (!matchOne(text, p)) { ok = false; issues.push("missing:" + p); } });
      if (c.expectAny && c.expectAny.length && !c.expectAny.some(function (p) { return matchOne(text, p); })) {
        ok = false; issues.push("none-of");
      }
      (c.reject || []).forEach(function (p) { if (matchOne(text, p)) { ok = false; issues.push("rejected:" + p); } });
      stats.total++;
      if (ok) stats.pass++;
      var b = stats.byGenerator[GENERATORS[g].id] || (stats.byGenerator[GENERATORS[g].id] = { total: 0, pass: 0 });
      b.total++; if (ok) b.pass++;
      out.push({ id: c.id, cat: c.cat, generator: GENERATORS[g].id, original: c.q,
                 variant: variant, output: text, route: res.route, latency_ms: res.latency_ms,
                 pass: ok, issues: issues });
      process.stdout.write(ok ? "." : "F");
    }
  }
  process.stdout.write("\n");
  stats.accuracy_pct = Math.round((stats.pass / Math.max(1, stats.total)) * 1000) / 10;
  var p = path.isAbsolute(OUT) ? OUT : path.join(rt.ROOT, OUT);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, JSON.stringify({ stats: stats, results: out }, null, 1));
  console.log(JSON.stringify(stats, null, 1));
  console.log("wrote " + p);
}
main().catch(function (e) { console.error(e); process.exit(1); });
